"""One-domain CPU controller backend; normalized capacities, no external LP runtime.

The controller of the protocol is the projection

    route:  min h + 0.5*rho*sum_live (z[e]-V[e])**2   s.t. h >= 0, z[e] <= h
    admit:  min     0.5*rho*sum_live (z[e]-V[e])**2   s.t. h = 1,  z[e] <= 1

with a signed ``z`` (no lower bound) and the ceiling ``h``.  For a fixed
ceiling the optimal consensus vector is ``z[e] = min(V[e], h)``; the optimal
ceiling solves ``rho*sum_live (V[e]-h)_+ = 1`` whenever that is attainable and
is zero otherwise.  The solution is therefore computed directly, without any
external solver dependency.
"""
from __future__ import annotations

import numpy as np


class PDLPMLU:

    def __init__(self, num_edges, rho, mode):
        self._num_edges = int(num_edges)
        self._num_domains = 1
        self._objective = mode
        self._NUM_VARIABLES = self._num_edges + 1
        self._NUM_CONSTRAINTS = self._num_edges
        self.rho = float(rho)
        self.alpha = 1.0
        self._solved = False
        self._current_F = np.zeros(self._num_edges)
        self.active = np.ones(self._num_edges, dtype=bool)
        self._solution = np.zeros(self._NUM_VARIABLES)

    # ------------------------------------------------------------------
    @property
    def num_edges(self):
        return self._num_edges

    @property
    def num_domains(self):
        return self._num_domains

    @property
    def is_mlu(self):
        return self._objective == 'route'

    @property
    def mode(self):
        return self._objective

    @mode.setter
    def mode(self, value):
        self._objective = value
        self._solved = False

    # ------------------------------------------------------------------
    def _get_variable_lower_bound_vector(self):
        out = np.full((self._NUM_VARIABLES,), -np.inf)
        out[-1] = 0.0 if self.is_mlu else 1.0
        return out

    def _get_variable_upper_bound_vector(self):
        out = np.full((self._NUM_VARIABLES,), np.inf)
        if not self.is_mlu:
            out[-1] = 1.0
        return out

    def _get_objective_matrix_diagonal(self):
        d = np.full((self._NUM_VARIABLES,), fill_value=float(self.rho))
        d[-1] = 0
        return d

    def _get_objective_vector(self):
        out = np.zeros((self._NUM_VARIABLES,))
        out[:-1] = -self._current_F * self.rho
        if self.is_mlu:
            out[-1] = self.alpha * self.num_domains
        return out

    def update_F_m(self, new_F, rho=None):
        if rho is not None:
            self.rho = float(rho)
        self._current_F = np.array(new_F, dtype=np.float64).flatten()
        self._solved = False

    # ------------------------------------------------------------------
    def _excess(self, ceiling, values):
        """``sum_live (V[e]-h)_+`` for the live entries."""
        if values.size == 0:
            return 0.0
        return float(np.sum(np.maximum(values - ceiling, 0.0)))

    def _ceiling(self, values):
        """The optimal ceiling of the route objective."""
        if values.size == 0:
            return 0.0
        if self.rho * self._excess(0.0, values) <= 1.0:
            return 0.0
        low = 0.0
        high = float(np.max(values))
        for _ in range(200):
            middle = 0.5 * (low + high)
            if self.rho * self._excess(middle, values) > 1.0:
                low = middle
            else:
                high = middle
        ceiling = high
        # Newton polish on the piecewise linear excess; the ceiling only moves
        # upwards so that the dual residual stays non negative.
        for _ in range(8):
            active = values > ceiling
            count = int(np.count_nonzero(active))
            if count == 0:
                break
            value = self.rho * self._excess(ceiling, values) - 1.0
            if value <= 0.0:
                break
            ceiling = ceiling + value / (self.rho * count)
        return ceiling

    def solve(self):
        """Solve the controller projection and return ``[z..., h]``."""
        values = self._current_F[self.active]
        if self.is_mlu:
            ceiling = self._ceiling(values)
        else:
            ceiling = 1.0
        z = np.zeros(self._num_edges)
        if self.active.any():
            z[self.active] = np.minimum(self._current_F[self.active], ceiling)
        self._solution = np.concatenate([z, np.array([ceiling])])
        self._solved = True
        return self._solution

    @property
    def current_u(self):
        return float(self._solution[-1])

    @property
    def current_Z(self):
        return self._solution[:-1]
